func newSeriesTestStore(t *testing.T) *Store {
	t.Helper()
	db, err := Open(filepath.Join(t.TempDir(), "data.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { _ = db.Close() })
	if err := db.EnsureGarminSeriesState(); err != nil {
		t.Fatalf("ensure: %v", err)
	}
	return db
}

func TestEnsureGarminSeriesState_IsIdempotent(t *testing.T) {
	db := newSeriesTestStore(t)
	for i := 0; i < 3; i++ {
		if err := db.EnsureGarminSeriesState(); err != nil {
			t.Fatalf("call %d: %v", i, err)
		}
	}
}

func TestGarminSeriesState_AbsentSeriesIsZeroNotAnError(t *testing.T) {
	db := newSeriesTestStore(t)
	st, err := db.GetGarminSeriesState("never_run")
	if err != nil {
		t.Fatalf("a series that has never run must read as zero state, not an error: %v", err)
	}
	if st.Series != "never_run" || st.LastCompleteDay != "" || st.TotalRows != 0 {
		t.Fatalf("state = %+v, want zero state carrying only the series name", st)
	}
}

func TestGarminSeriesState_RoundTripsAndUpdatesInPlace(t *testing.T) {
	db := newSeriesTestStore(t)
	want := GarminSeriesState{
		Series: "steps", LastCompleteDay: "2026-09-07", EarliestDay: "2020-07-06",
		FrontierDay: "2019-08-15", StopReason: "empty_window_ceiling", EmptyWindows: 13, TotalRows: 2251,
	}
	if err := db.SaveGarminSeriesState(want); err != nil {
		t.Fatalf("save: %v", err)
	}
	got, err := db.GetGarminSeriesState("steps")
	if err != nil {
		t.Fatalf("get: %v", err)
	}
	if got.LastCompleteDay != want.LastCompleteDay || got.EarliestDay != want.EarliestDay ||
		got.FrontierDay != want.FrontierDay || got.StopReason != want.StopReason ||
		got.EmptyWindows != want.EmptyWindows || got.TotalRows != want.TotalRows {
		t.Fatalf("round trip = %+v, want %+v", got, want)
	}
	if got.UpdatedAt.IsZero() {
		t.Fatal("updated_at was not stamped")
	}

	want.LastCompleteDay = "2026-09-08"
	if err := db.SaveGarminSeriesState(want); err != nil {
		t.Fatalf("update: %v", err)
	}
	list, err := db.ListGarminSeriesState()
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	if len(list) != 1 {
		t.Fatalf("a second save created %d rows; it must update in place", len(list))
	}
	if list[0].LastCompleteDay != "2026-09-08" {
		t.Fatalf("update did not take: %+v", list[0])
	}
}

func TestSaveGarminSeriesState_RejectsAnUnnamedSeries(t *testing.T) {
	db := newSeriesTestStore(t)
	if err := db.SaveGarminSeriesState(GarminSeriesState{}); err == nil {
		t.Fatal("saving state with no series name must be refused, not stored under a blank key")
	}
}

// The generated sync_state table is a separate projection: clearing one must
// not touch the other. This is why the windowed bookmark lives in its own
// table — earliest_day costs a multi-year re-walk to rebuild.
func TestGarminSeriesState_SurvivesAGeneratedSyncCursorClear(t *testing.T) {
	db := newSeriesTestStore(t)
	if err := db.SaveGarminSeriesState(GarminSeriesState{
		Series: "steps", LastCompleteDay: "2026-09-07", EarliestDay: "2020-07-06", TotalRows: 2251,
	}); err != nil {
		t.Fatalf("save: %v", err)
	}
	if err := db.SaveSyncState("steps", "2026-09-07", 2251); err != nil {
		t.Fatalf("mirror: %v", err)
	}
	if err := db.ClearSyncCursors(); err != nil {
		t.Fatalf("clear: %v", err)
	}
	st, err := db.GetGarminSeriesState("steps")
	if err != nil {
		t.Fatalf("get after clear: %v", err)
	}
	if st.EarliestDay != "2020-07-06" {
		t.Fatalf("earliest_day = %q after a generated cursor clear; the windowed bookmark must survive it", st.EarliestDay)
	}
}

func TestUpsertKeyedBatch_StoresUnderTheCallerSuppliedID(t *testing.T) {
	db := newSeriesTestStore(t)
	rows := []KeyedRow{
		{ID: "2026-09-06", Data: json.RawMessage(`{"calendarDate":"2026-09-06","totalSteps":8000,"stepGoal":7500}`)},
		{ID: "2026-09-07", Data: json.RawMessage(`{"calendarDate":"2026-09-07","totalSteps":9100,"stepGoal":7500}`)},
	}
	stored, skipped, err := db.UpsertKeyedBatch("steps", rows)
	if err != nil {
		t.Fatalf("upsert: %v", err)
	}
	if stored != 2 || skipped != 0 {
		t.Fatalf("stored=%d skipped=%d, want 2/0", stored, skipped)
	}
	if _, err := db.Get("steps", "2026-09-06"); err != nil {
		t.Fatalf("row not stored under its calendar-date key: %v", err)
	}
	// The typed projection fires for a resource that has a typed table, so
	// SQL and analytics readers see the day too.
	var n int
	if err := db.DB().QueryRow(`SELECT COUNT(*) FROM "steps" WHERE id = ?`, "2026-09-06").Scan(&n); err != nil {
		t.Fatalf("typed table query: %v", err)
	}
	if n != 1 {
		t.Fatalf("typed steps rows for 2026-09-06 = %d, want 1", n)
	}
}

func TestUpsertKeyedBatch_IsIdempotentAcrossReruns(t *testing.T) {
	db := newSeriesTestStore(t)
	row := []KeyedRow{{ID: "2026-09-06", Data: json.RawMessage(`{"calendarDate":"2026-09-06","totalSteps":8000}`)}}
	for i := 0; i < 3; i++ {
		if _, _, err := db.UpsertKeyedBatch("steps", row); err != nil {
			t.Fatalf("run %d: %v", i, err)
		}
	}
	n, err := db.CountResourceRows("steps")
	if err != nil {
		t.Fatalf("count: %v", err)
	}
	if n != 1 {
		t.Fatalf("three identical runs produced %d rows, want 1", n)
	}
}

func TestUpsertKeyedBatch_SkipsRowsWithNoKeyOrNoBody(t *testing.T) {
	db := newSeriesTestStore(t)
	stored, skipped, err := db.UpsertKeyedBatch("steps", []KeyedRow{
		{ID: "", Data: json.RawMessage(`{"totalSteps":1}`)},
		{ID: "2026-09-06", Data: nil},
		{ID: "2026-09-07", Data: json.RawMessage(`[1,2,3]`)}, // not an object
		{ID: "2026-09-08", Data: json.RawMessage(`{"calendarDate":"2026-09-08"}`)},
	})
	if err != nil {
		t.Fatalf("upsert: %v", err)
	}
	if stored != 1 || skipped != 3 {
		t.Fatalf("stored=%d skipped=%d, want 1/3: an unkeyed or unusable row must be skipped and counted, never stored under a blank key", stored, skipped)
	}
	var blank int
	if err := db.DB().QueryRow(`SELECT COUNT(*) FROM resources WHERE resource_type = 'steps' AND id = ''`).Scan(&blank); err != nil {
		t.Fatalf("blank key query: %v", err)
	}
	if blank != 0 {
		t.Fatalf("%d rows landed under a blank key", blank)
	}
}

func TestUpsertKeyedBatch_EmptyInputIsANoOp(t *testing.T) {
	db := newSeriesTestStore(t)
	stored, skipped, err := db.UpsertKeyedBatch("steps", nil)
	if err != nil || stored != 0 || skipped != 0 {
		t.Fatalf("empty batch = (%d, %d, %v), want (0, 0, nil)", stored, skipped, err)
	}
}

func TestMissingResourceIDs_ReturnsOnlyWhatIsAbsent(t *testing.T) {
	db := newSeriesTestStore(t)
	if _, _, err := db.UpsertKeyedBatch("activity_hr_zones", []KeyedRow{
		{ID: "2", Data: json.RawMessage(`{"activityId":"2"}`)},
	}); err != nil {
		t.Fatalf("seed: %v", err)
	}
	missing, err := db.MissingResourceIDs("activity_hr_zones", []string{"1", "2", "3"})
	if err != nil {
		t.Fatalf("missing: %v", err)
	}
	if len(missing) != 2 || missing[0] != "1" || missing[1] != "3" {
		t.Fatalf("missing = %v, want [1 3]", missing)
	}
	if none, err := db.MissingResourceIDs("activity_hr_zones", nil); err != nil || none != nil {
		t.Fatalf("empty input = (%v, %v), want (nil, nil)", none, err)
	}
}

func TestResourceIDsNewestFirst_RespectsTheLimit(t *testing.T) {
	db := newSeriesTestStore(t)
	for _, id := range []string{"1", "2", "3"} {
		if _, _, err := db.UpsertKeyedBatch("activities", []KeyedRow{
			{ID: id, Data: json.RawMessage(`{"activityId":` + id + `}`)},
		}); err != nil {
			t.Fatalf("seed %s: %v", id, err)
		}
	}
	all, err := db.ResourceIDsNewestFirst("activities", 0)
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	if len(all) != 3 {
		t.Fatalf("got %d ids, want 3", len(all))
	}
	capped, err := db.ResourceIDsNewestFirst("activities", 2)
	if err != nil {
		t.Fatalf("list capped: %v", err)
	}
	if len(capped) != 2 {
		t.Fatalf("got %d ids under a limit of 2", len(capped))
	}
}
